package com.example.planyourtrip.controller;
import com.example.planyourtrip.dto.TimelineDto; import com.example.planyourtrip.security.AuthUser; import com.example.planyourtrip.service.TimelineService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/trips/{tripId}/timelines") public class TimelineController { private final TimelineService s; public TimelineController(TimelineService s){this.s=s;} @GetMapping List<TimelineDto> list(@AuthUser Long uid,@PathVariable Long tripId){return s.list(uid,tripId);} @PostMapping TimelineDto create(@AuthUser Long uid,@PathVariable Long tripId,@Valid @RequestBody TimelineDto d){return s.create(uid,tripId,d);} @PutMapping("/{id}") TimelineDto update(@AuthUser Long uid,@PathVariable Long id,@Valid @RequestBody TimelineDto d){return s.update(uid,id,d);} @DeleteMapping("/{id}") void delete(@AuthUser Long uid,@PathVariable Long id){s.delete(uid,id);} }
